<?= view('partials/header',['pageTitle'=>'Request a quote']) ?><section class="section wrap narrow"><span class="eyebrow">GET STARTED</span><h1>Request a free quote</h1><p class="lead">Share your needs and our team can review your inquiry.</p><form class="formcard" action="<?= site_url('quote') ?>" method="post"><?= csrf_field() ?><label>Your name<input name="contact_name" maxlength="200" required value="<?= esc(old('contact_name')) ?>"></label><label>Email<input type="email" name="contact_email" maxlength="255" required value="<?= esc(old('contact_email')) ?>"></label><label>Phone (optional)<input name="contact_phone" maxlength="30" value="<?= esc(old('contact_phone')) ?>"></label><label>Service (optional)<select name="service_id"><option value="">Not sure yet</option><?php foreach($services as $s): ?><option value="<?= (int)$s['service_id'] ?>" <?= (string)(old('service_id') ?: service('request')->getGet('service_id')) === (string)$s['service_id'] ? 'selected' : '' ?>><?= esc($s['service_name']) ?></option><?php endforeach; ?></select></label><label>Tell us about your project<textarea name="details" rows="5" maxlength="5000" required><?= esc(old('details')) ?></textarea></label><button class="btn" type="submit">Submit quote request</button></form></section><?= view('partials/footer') ?>
